// index.js with types.
export interface Book {
  title: string;
  pages: number;
}

type Books = Record<string, Book>;

export function take(
  shelf: Shelf,
  title: string,
): Book {
  const book: Book | undefined = shelf.books[title];
  if (book === undefined) throw new RangeError("no book " + title);
  return book;
}

export class Shelf {
  books: Books = {};

  put(title: string, pages: number): this {
    if (pages < 0) {
      throw new RangeError("pages " + pages);
    }
    this.books[title] = { title, pages };
    return this;
  }

  get first(): string {
    return Object.keys(this.books)[0]!.toUpperCase();
  }

  each(visit: (book: Book) => void): this {
    for (const title in this.books) visit(this.books[title]!);
    return this;
  }
}

export function where(): string {
  return new Error("here").stack as string;
}

export const pagesOf = (shelf: Shelf, title: string): number =>
  shelf.books[title]!.pages;

export function callMissing(shelf: any): unknown {
  return (shelf as { missing(a: number, b: number): unknown }).missing(1, 2);
}

export function construct(value: any): unknown {
  return new value.Maker(
    "é€",
    1,
  );
}

interface Pair {
  left: number;
  right: number;
}

export async function later(shelf: Shelf, title: string): Promise<Book> {
  await null;
  return take(shelf, title);
}

export function tagged(tag: any): unknown {
  return tag`a${1}b`;
}

export function mapped(list: { name: string }[]): number[] {
  return list.map<number>(
    (item: { name: string }): number => item.name.length,
  );
}

export function chained(a: any): unknown {
  return a.b
    .c()
    .d;
}

export function afterText(a: any): string {
  return "é€😀" + (a.b satisfies unknown).c;
}
